          "stem": "다음은 호환성(Compatibility)의 어떤 부특성을 설명한 것인가?\n다른 SW에 영향 없이 자원을 공유하면서 기능을 작동할 수 있는 정도\n예) 보안 프로그램을 여러 곳에서 다운로드받아 설치할 때 기존의 애플리케이션이 정상적\n으로 동작하지 않는 경우→ 설치된 보안프로그램들이 메모리와 같은 자원을 사용하여\n충돌이 일어나거나 자원을 독점적으로 사용할 때 발생",
