          "type": "short_answer",
          "stem": "다음은 ISO/IEC 25010 제품 품질 모델의 8가지 품질 주특성 중 하나에 대한 설명이다. 어떤\n품질 특성을 설명한 것인지 기술하시오.\n∎ 시스템, 제품 또는 컴포넌트가 지정된 기간 동안 명시된 조건에서 명시된 기능을\n수행하는 정도\n∎ 부특성은 성숙성 (Maturity), 가용성 (Availability), 결함 허용성 (Fault tolerance), 복구성\n(Recoverability)으로 구성됨",
